update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(153,null::text,$$Relatório mensal do estabelecimento$$,$$O estabelecimento designado encaminha mensalmente ao juiz da execução relatório e comunica, a qualquer tempo, a ausência ou falta disciplinar do condenado.$$),
(154,null,$$Comunicação da pena aplicada$$,$$Cabe ao juiz da execução comunicar à autoridade competente a pena aplicada, determinada a intimação do condenado. Na pena de interdição do artigo 47, inciso I, do Código Penal, a autoridade baixa ato em 24 (vinte e quatro) horas do recebimento do ofício, e a execução inicia-se a partir dele (§ 1º). Nas hipóteses do artigo 47, incisos II e III, do Código Penal, o juízo determina a apreensão dos documentos que autorizam o exercício do direito interditado (§ 2º).$$),
(155,null,$$Comunicação do descumprimento da pena$$,$$A autoridade deve comunicar imediatamente ao juiz da execução o descumprimento da pena. A comunicação pode ser feita por qualquer prejudicado (parágrafo único).$$),
(156,null,$$Suspensão condicional da pena$$,$$O juiz pode suspender, por 2 (dois) a 4 (quatro) anos, a execução da pena privativa de liberdade não superior a 2 (dois) anos, na forma dos artigos 77 a 82 do Código Penal.$$),
(157,null,$$Pronunciamento sobre a suspensão condicional$$,$$O juiz ou tribunal, na sentença que aplicar pena privativa de liberdade na situação do artigo anterior, deve pronunciar-se motivadamente sobre a suspensão condicional, quer a conceda, quer a denegue.$$),
(158,null,$$Condições da suspensão condicional$$,$$Concedida a suspensão, o juiz especifica as condições a que fica sujeito o condenado, pelo prazo fixado, que começa a correr da audiência do artigo 160. As condições são adequadas ao fato e à situação pessoal do condenado, incluindo a de prestar serviços à comunidade ou limitação de fim de semana, salvo a hipótese do artigo 78, § 2º, do Código Penal (§ 1º). O juiz pode modificá-las a qualquer tempo, ouvido o condenado (§ 2º), a fiscalização é atribuída a serviço social penitenciário, Patronato, Conselho da Comunidade ou instituição beneficiada (§ 3º), e o beneficiário comunica à entidade fiscalizadora sua ocupação e os salários ou proventos de que vive (§ 4º).$$),
(159,null,$$Suspensão concedida por Tribunal$$,$$Quando a suspensão condicional for concedida por Tribunal, a este cabe estabelecer as condições do benefício, o mesmo ocorrendo quando o Tribunal modificar as condições da sentença recorrida (§ 1º). O Tribunal pode conferir ao juízo da execução a incumbência de estabelecer as condições (§ 2º).$$),
(160,null,$$Audiência admonitória$$,$$Transitada em julgado a sentença condenatória, o juiz a lê ao condenado, em audiência, advertindo-o das consequências de nova infração penal e do descumprimento das condições impostas.$$),
(161,null,$$Ausência à audiência admonitória$$,$$Se, intimado pessoalmente ou por edital com prazo de 20 (vinte) dias, o réu não comparecer injustificadamente à audiência admonitória, a suspensão fica sem efeito e a pena é executada imediatamente.$$),
(162,null,$$Revogação e prorrogação do período de prova$$,$$A revogação da suspensão condicional da pena e a prorrogação do período de prova ocorrem na forma do artigo 81 e respectivos parágrafos do Código Penal.$$),
(163,null,$$Registro da sentença com suspensão$$,$$A sentença condenatória é registrada, com a nota de suspensão, em livro especial do juízo a que couber a execução da pena. Revogada a suspensão ou extinta a pena, o fato é averbado à margem do registro (§ 1º), e o registro e a averbação são sigilosos, salvo informações requisitadas por órgão judiciário ou pelo Ministério Público para instruir processo penal (§ 2º).$$),
(164,null,$$Execução da pena de multa$$,$$Extraída certidão da sentença condenatória com trânsito em julgado, que vale como título executivo judicial, o Ministério Público requer, em autos apartados, a citação do condenado para, em 10 (dez) dias, pagar o valor da multa ou nomear bens à penhora. Decorrido o prazo sem pagamento ou depósito, procede-se à penhora de tantos bens quantos bastem para garantir a execução (§ 1º), e a nomeação de bens e a execução seguem a lei processual civil (§ 2º).$$),
(165,null,$$Penhora de bem imóvel$$,$$Se a penhora recair em bem imóvel, os autos apartados são remetidos ao Juízo Cível para prosseguimento.$$),
(166,null,$$Penhora de outros bens$$,$$Recaindo a penhora em outros bens, dá-se prosseguimento nos termos do § 2º do artigo 164.$$),
(167,null,$$Suspensão da execução da multa$$,$$A execução da pena de multa é suspensa quando sobrevier ao condenado doença mental (artigo 52 do Código Penal).$$),
(168,null,$$Desconto da multa em vencimento ou salário$$,$$O juiz pode determinar que a cobrança da multa se efetue mediante desconto no vencimento ou salário do condenado, nas hipóteses do artigo 50, § 1º, do Código Penal. O desconto mensal tem limite máximo de um quarto da remuneração e mínimo de um décimo (inciso I), é feito mediante ordem do juiz (inciso II) e o responsável é intimado a recolher mensalmente a importância determinada, até o dia fixado (inciso III).$$),
(169,null,$$Pagamento da multa em prestações$$,$$Até o término do prazo do artigo 164, o condenado pode requerer ao juiz o pagamento da multa em prestações mensais, iguais e sucessivas. O juiz pode determinar diligências sobre a situação econômica do condenado e, ouvido o Ministério Público, fixa o número de prestações (§ 1º). Se o condenado for impontual ou melhorar de situação econômica, o benefício é revogado, executando-se a multa (§ 2º).$$),
(170,null,$$Multa cumulada com pena privativa de liberdade$$,$$Quando a multa é aplicada cumulativamente com pena privativa de liberdade, pode ser cobrada mediante desconto na remuneração do condenado enquanto esta é executada (artigo 168). Se o condenado cumprir a pena privativa de liberdade ou obtiver livramento condicional sem ter resgatado a multa, a cobrança segue os termos do Capítulo (§ 1º), o que se aplica também à suspensão condicional da pena (§ 2º).$$),
(171,null,$$Guia na medida de segurança$$,$$Transitada em julgado a sentença que aplicar medida de segurança, ordena-se a expedição de guia para a execução.$$),
(172,null,$$Internação ou tratamento mediante guia$$,$$Ninguém é internado em Hospital de Custódia e Tratamento Psiquiátrico, ou submetido a tratamento ambulatorial para cumprimento de medida de segurança, sem a guia expedida pela autoridade judiciária.$$),
(173,null,$$Conteúdo da guia de internamento ou tratamento$$,$$A guia é extraída pelo escrivão, que a rubrica em todas as folhas e a subscreve com o juiz, e é remetida à autoridade administrativa incumbida da execução. Contém a qualificação do agente e o número do registro geral (inciso I), o inteiro teor da denúncia e da sentença e a certidão do trânsito em julgado (inciso II), a data em que terminará o prazo mínimo de internação ou do tratamento ambulatorial (inciso III) e outras peças reputadas indispensáveis (inciso IV). Dá-se ciência ao Ministério Público (§ 1º) e a guia é retificada sempre que sobrevierem modificações quanto ao prazo de execução (§ 2º).$$),
(174,null,$$Aplicação dos arts. 8º e 9º$$,$$Aplicam-se na execução da medida de segurança, naquilo que couber, os artigos 8º e 9º da Lei.$$),
(175,null,$$Cessação da periculosidade$$,$$A cessação da periculosidade é averiguada no fim do prazo mínimo de duração da medida de segurança, pelo exame das condições pessoais do agente. A autoridade administrativa remete ao juiz, até 1 (um) mês antes de expirar o prazo mínimo, minucioso relatório (inciso I), instruído com o laudo psiquiátrico (inciso II); ouvem-se sucessivamente o Ministério Público e o curador ou defensor, em 3 (três) dias para cada um (inciso III), nomeando o juiz curador ou defensor a quem não o tiver (inciso IV), e o juiz decide em 5 (cinco) dias (inciso VI).$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;